import{_ as e,o as t,c as i,a2 as s}from"./chunks/framework.doxMM-x8.js";const b=JSON.parse('{"title":"Existing Platform Capabilities","description":"","frontmatter":{"docLocale":"en","counterpart":"/guides/platform","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/guides/platform.md","filePath":"en/guides/platform.md"}'),r={name:"en/guides/platform.md"};function n(o,a,d,l,p,c){return t(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="existing-platform-capabilities" tabindex="-1">Existing Platform Capabilities <a class="header-anchor" href="#existing-platform-capabilities" aria-label="Permalink to &quot;Existing Platform Capabilities&quot;">​</a></h1><p>Goal: reuse existing platform interfaces when developing Lab Word and understand their boundary with laboratory behavior. Complete <a href="./../getting-started/quickstart">quick start</a>first.</p><h2 id="start-with-real-interfaces" tabindex="-1">Start With Real Interfaces <a class="header-anchor" href="#start-with-real-interfaces" aria-label="Permalink to &quot;Start With Real Interfaces&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/api/v1/auth/session</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/api/openapi.json</span></span></code></pre></div><p>An anonymous session request should return 401; OpenAPI should return JSON identifying <code>Lab Word API</code>. Signed-in views use Session through the SDK. Business mutations retain trusted Origin and CSRF checks; visible client controls do not replace server authorization.</p><h2 id="source-and-responsibilities" tabindex="-1">Source And Responsibilities <a class="header-anchor" href="#source-and-responsibilities" aria-label="Permalink to &quot;Source And Responsibilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Public source</th><th>Lab responsibility</th></tr></thead><tbody><tr><td>Registration, sessions, password reset</td><td><a href="https://github.com/CaiZongyuan/labworld/blob/240294a75a807367d3bad8fa0b1a14e26ecc1828/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer">Identity</a></td><td>Reuse User and Session</td></tr><tr><td>Organization membership and roles</td><td><a href="https://github.com/CaiZongyuan/labworld/blob/240294a75a807367d3bad8fa0b1a14e26ecc1828/crates/app/src/modules/organization/mod.rs" target="_blank" rel="noreferrer">Organization</a></td><td>Define equipment resource access</td></tr><tr><td>Files and cleanup</td><td><a href="https://github.com/CaiZongyuan/labworld/blob/240294a75a807367d3bad8fa0b1a14e26ecc1828/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer">Files</a></td><td>Define future asset ownership; M0 local imports do not upload</td></tr><tr><td>Jobs, audit, notifications</td><td><a href="https://github.com/CaiZongyuan/labworld/blob/240294a75a807367d3bad8fa0b1a14e26ecc1828/crates/app/src/modules/jobs/mod.rs" target="_blank" rel="noreferrer">Jobs</a>, <a href="https://github.com/CaiZongyuan/labworld/blob/240294a75a807367d3bad8fa0b1a14e26ecc1828/crates/app/src/modules/audit/mod.rs" target="_blank" rel="noreferrer">Audit</a>, <a href="https://github.com/CaiZongyuan/labworld/blob/240294a75a807367d3bad8fa0b1a14e26ecc1828/crates/app/src/modules/notifications/mod.rs" target="_blank" rel="noreferrer">Notifications</a></td><td>Define handlers, audit semantics and notification targets</td></tr><tr><td>Knowledge base</td><td><a href="https://github.com/CaiZongyuan/labworld/blob/240294a75a807367d3bad8fa0b1a14e26ecc1828/crates/app/src/modules/knowledge/mod.rs" target="_blank" rel="noreferrer">Knowledge</a></td><td>Keep existing behavior separate from equipment models</td></tr></tbody></table><p>Read the <a href="./../reference/api">generated API</a>for operations and responses and <a href="./../reference/config">configuration</a>for settings. Platform capabilities do not imply implemented telemetry, IoT integration or equipment control.</p><h2 id="validate-failure-boundaries" tabindex="-1">Validate Failure Boundaries <a class="header-anchor" href="#validate-failure-boundaries" aria-label="Permalink to &quot;Validate Failure Boundaries&quot;">​</a></h2><p>Run from the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> registration</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sessions</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:frontend</span></span></code></pre></div><p>Backend checks start isolated services and verify registration, sessions, rejection and invalidation with real dependencies; Docker is required. Frontend checks use MSW at HTTP and do not prove database or storage integration. Choose relevant checks with the <a href="./../testing/feedback-loop">testing guide</a>.</p><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/labworld/blob/240294a75a807367d3bad8fa0b1a14e26ecc1828/compose.production.yaml" target="_blank" rel="noreferrer">compose.production.yaml</a>defines existing deployment, with <a href="https://github.com/CaiZongyuan/labworld/blob/240294a75a807367d3bad8fa0b1a14e26ecc1828/deploy/production/env.production.example" target="_blank" rel="noreferrer">env.production.example</a>as the configuration example. <a href="https://github.com/CaiZongyuan/labworld/blob/240294a75a807367d3bad8fa0b1a14e26ecc1828/justfile" target="_blank" rel="noreferrer">justfile</a>provides explicit migration, deployment, backup and isolated restore commands. Inspect current scripts and settings first; this page does not claim a production Lab release exists.</p><hr><p>Source version：<code>240294a75a80</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/240294a75a807367d3bad8fa0b1a14e26ecc1828/docs/guides/platform.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,16)])])}const u=e(r,[["render",n]]);export{b as __pageData,u as default};
